const CLOUD = [[0, 0, 1], [-0.9, 0.25, 0.7], [0.9, 0.2, 0.75], [-0.45, -0.45, 0.72], [0.4, -0.55, 0.8], [1.5, 0.45, 0.5], [-1.5, 0.5, 0.48], [0, -0.95, 0.55]];
