  if (!opts.noWing) { g.fillStyle = '#ffffff'; g.beginPath(); g.moveTo(-8, -32); g.quadraticCurveTo(-30, -90 - w * 30, 20, -105 - w * 35); g.quadraticCurveTo(10, -60, 12, -32); g.fill();
    g.strokeStyle = '#d4dcec'; g.lineWidth = 1.5; for (let i = 0; i < 4; i++) { g.beginPath(); g.moveTo(-4 + i * 4, -34); g.lineTo(-10 + i * 8, -70 - w * 20 - i * 6); g.stroke(); } }
