/* ---------- paper grain + vignette (pre-rendered once) ---------- */
let paper = null;
function paperLayer() {
  if (paper) return paper;
  paper = document.createElement('canvas'); paper.width = W; paper.height = H;
  const p = paper.getContext('2d'), img = p.createImageData(W, H), r = rng(42);
  for (let i = 0; i < img.data.length; i += 4) { const v = 200 + r() * 55; img.data[i] = v; img.data[i + 1] = v - 6; img.data[i + 2] = v - 18; img.data[i + 3] = 22 + r() * 18; }
  p.putImageData(img, 0, 0);
  const vg = p.createRadialGradient(W / 2, H / 2, H * 0.35, W / 2, H / 2, H * 0.95);
  vg.addColorStop(0, 'rgba(40,30,60,0)'); vg.addColorStop(1, 'rgba(40,30,60,0.38)');
  p.fillStyle = vg; p.fillRect(0, 0, W, H);
  return paper;
}
function finish(g) { g.save(); g.globalCompositeOperation = 'multiply'; g.drawImage(paperLayer(), 0, 0); g.restore(); }

